"""Conveniences for working with the toolchains that produce GBL files.

Nothing here is part of the GBL format itself.
"""

from __future__ import annotations

import re

from pygbl.crypto import AES_KEY_SIZE
from pygbl.types import ParseError

# Simplicity Studio stores the image encryption key as a manufacturing token file:
#
#     # Key randomly generated by 'commander ebl keygen'
#     TOKEN_MFG_SECURE_BOOTLOADER_KEY: 7F8FE53979B31BC556FCB131AFF42414
#
ENCRYPTION_KEY_TOKEN = "TOKEN_MFG_SECURE_BOOTLOADER_KEY"


def read_encryption_key(data: str | bytes) -> bytes:
    """Read an image encryption key from a manufacturing token file's contents."""
    if isinstance(data, bytes):
        data = data.decode("utf-8")

    match = re.search(
        rf"^\s*{ENCRYPTION_KEY_TOKEN}\s*:\s*([0-9A-Fa-f]+)\s*$", data, re.MULTILINE
    )

    if match is None:
        raise ParseError(f"No {ENCRYPTION_KEY_TOKEN} found in key file")

    key = bytes.fromhex(match.group(1))

    if len(key) != AES_KEY_SIZE:
        raise ParseError(f"Key must be {AES_KEY_SIZE} bytes, got {len(key)}")

    return key
